  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Flupirtine, the closest analogue (Morgan 0.65), shares the ethyl carbamate and 4-fluorobenzylamino core; its absolute oral bioavailability was 90% in healthy volunteers versus IV, strongly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Safinamide, a fluorobenzyl-containing drug with a similar polar carboxamide/amine motif, has an absolute oral bioavailability of about 95% in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lumiracoxib, a fluorinated aromatic drug, showed 74.0 ± 8.6% absolute oral bioavailability in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogue flupirtine has high absolute oral bioavailability (90%) in humans, and multiple structurally related fluorobenzyl/carbamate drugs show F >= 74%; therefore the query is predicted to have high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "The query differs from flupirtine by replacing a pyridine ring nitrogen with a carbon bearing an amino group, which may alter solubility and metabolic stability.",
    "Metabolic clearance and intestinal permeability of the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

